CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,name VARCHAR(255) NOT NULL DEFAULT '',role_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS profiles(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,education VARCHAR(255) NOT NULL DEFAULT '',experience INT NOT NULL DEFAULT 0,interests TEXT NOT NULL,CONSTRAINT fk_profiles_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,category VARCHAR(80) NOT NULL,aliases TEXT NOT NULL,description TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,family VARCHAR(80) NOT NULL,summary TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_skills(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,skill_id INT NOT NULL,level INT NOT NULL DEFAULT 1,evidence VARCHAR(40) NOT NULL DEFAULT 'self_reported',UNIQUE KEY uq_user_skill(user_id,skill_id),CONSTRAINT fk_us_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_us_skill FOREIGN KEY(skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requirements(id INT AUTO_INCREMENT PRIMARY KEY,role_id INT NOT NULL,skill_id INT NOT NULL,weight DOUBLE NOT NULL,expected INT NOT NULL DEFAULT 3,UNIQUE KEY uq_role_skill(role_id,skill_id),CONSTRAINT fk_req_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,CONSTRAINT fk_req_skill FOREIGN KEY(skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dependencies(id INT AUTO_INCREMENT PRIMARY KEY,skill_id INT NOT NULL,prerequisite_id INT NOT NULL,UNIQUE KEY uq_dependency(skill_id,prerequisite_id),CONSTRAINT fk_dep_skill FOREIGN KEY(skill_id) REFERENCES skills(id),CONSTRAINT fk_dep_parent FOREIGN KEY(prerequisite_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL UNIQUE,description TEXT NOT NULL,difficulty VARCHAR(40) NOT NULL,hours INT NOT NULL,roles TEXT NOT NULL,skills TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roadmap(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,skill_id INT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'not_started',UNIQUE KEY uq_user_roadmap_skill(user_id,skill_id),CONSTRAINT fk_roadmap_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_roadmap_skill FOREIGN KEY(skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS history(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,role_id INT NOT NULL,score INT NOT NULL,created VARCHAR(40) NOT NULL,CONSTRAINT fk_history_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_history_role FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
